import{_ as e,o as d,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"Results","description":"Property reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started.","frontmatter":{"title":"Results","description":"Property reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started."},"headers":[],"relativePath":"laravel-myanmar-payments/references/results.md","filePath":"laravel-myanmar-payments/references/results.md"}'),a={name:"laravel-myanmar-payments/references/results.md"};function c(n,t,s,i,l,y){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns one of four classes in <code>Laranex\\PhpMyanmarPayments\\Results</code>. All implement <code>PaymentResult</code> and expose <code>flow(): PaymentFlow</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>kbzPay()-&gt;pwa()</code> and <code>waveMoney()-&gt;initiate()</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order id</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>gatewayReference</code></td><td><code>?string</code></td><td>The gateway&#39;s id for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>ayaPay()-&gt;initiate()</code> and <code>cyberSource()-&gt;initiate()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order id</td></tr><tr><td><code>action</code></td><td><code>string</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>fields</code></td><td><code>array&lt;string, string&gt;</code></td><td>The signed hidden fields. Post them unchanged</td></tr><tr><td><code>enctype</code></td><td><code>string</code></td><td>The form encoding the gateway expects</td></tr><tr><td><code>field($name)</code></td><td><code>?string</code></td><td>The value of one field</td></tr><tr><td><code>values()</code></td><td><code>array&lt;string, string&gt;</code></td><td>The fields as an array, e.g. for your own template</td></tr><tr><td><code>autoSubmitUrl</code></td><td><code>?string</code></td><td>Link to the package&#39;s auto-submitting page. <code>null</code> when the form route is disabled</td></tr><tr><td><code>withAutoSubmitUrl($url)</code></td><td><code>FormPayment</code></td><td>A copy with <code>autoSubmitUrl</code> set</td></tr><tr><td><code>toHtml()</code></td><td><code>string</code></td><td>A full HTML page that posts the form on load</td></tr></tbody></table><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>kbzPay()-&gt;qr()</code>, <code>yomaMmqr()-&gt;initiate()</code> and <code>yomaMmqr()-&gt;renewQr()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order id</td></tr><tr><td><code>qrString</code></td><td><code>?string</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>qrImage</code></td><td><code>?string</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>expiresAt</code></td><td><code>?DateTimeImmutable</code></td><td>When the QR stops being payable</td></tr><tr><td><code>reference</code></td><td><code>?string</code></td><td>The gateway&#39;s id for this QR (KBZ <code>prepay_id</code>, Yoma <code>refLabel</code>)</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>qrImageDataUri($mimeType = &#39;image/png&#39;)</code></td><td><code>?string</code></td><td><code>qrImage</code> as a data URI for <code>&lt;img src&gt;</code></td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>kbzPay()-&gt;app()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order id</td></tr><tr><td><code>orderInfo</code></td><td><code>string</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>sign</code></td><td><code>string</code></td><td>The signature of <code>orderInfo</code></td></tr><tr><td><code>signType</code></td><td><code>string</code></td><td><code>SHA256</code></td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>toArray()</code></td><td><code>array</code></td><td><code>orderId</code>, <code>orderInfo</code>, <code>sign</code>, <code>signType</code> for your mobile app</td></tr></tbody></table><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Value</th><th>Result</th></tr></thead><tbody><tr><td><code>PaymentFlow::Redirect</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>PaymentFlow::Form</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>PaymentFlow::Qr</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>PaymentFlow::App</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table>',16)])])}const p=e(a,[["render",c]]);export{h as __pageData,p as default};
